/**
 * frontend/src/components/CameraRecognition.jsx
 * 🎥 Reconnaissance faciale en direct
 * - Capture vidéo
 * - Envoi au backend
 * - Gestion des cas match / no match / erreur
 * - Messages d’instructions et bouton Reprendre
 */

import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  const [streaming, setStreaming] = useState(false);
  const [capturedImage, setCapturedImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);

  // ================= INIT CAMERA =================
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setStreaming(true);
    } catch (err) {
      console.error('Camera error:', err);
      addNotification('Impossible d’accéder à la caméra', 'error');
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
    }
    setStreaming(false);
  };

  // ================= CAPTURE IMAGE =================
  const captureImage = () => {
    if (!videoRef.current || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const video = videoRef.current;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0);

    const base64 = canvas.toDataURL('image/jpeg');
    setCapturedImage(base64);
    setResult(null);
  };

  // ================= RECOGNIZE =================
  const recognizeFace = async () => {
    if (!capturedImage) {
      addNotification('Veuillez capturer une image avant reconnaissance', 'error');
      return;
    }

    setLoading(true);
    setResult(null);

    try {
      const response = await attendanceAPI.recognize(capturedImage);

      if (response.success) {
        setResult({ status: 'success', data: response.data });
        addNotification(`Reconnu : ${response.data.student_name}`, 'success');
      } else if (response.isNoMatch) {
        setResult({ status: 'nomatch', data: response.data });
        addNotification('Visage inconnu', 'warning');
      } else if (response.error?.includes("No faces detected")) {
        setResult({ status: 'noface', error: "Aucun visage détecté. Veuillez vous rapprocher de la caméra et réessayer." });
        addNotification('Aucun visage détecté', 'error');
      } else {
        throw new Error(response.error || 'Erreur de reconnaissance');
      }
    } catch (err) {
      console.error('Recognition error:', err);
      setResult({ status: 'error', error: err.message });
      addNotification(`Erreur : ${err.message}`, 'error');
    }

    setLoading(false);
  };

  // ================= CLEANUP =================
  useEffect(() => {
    return () => stopCamera();
  }, []);

  // ================= RENDER =================
  return (
    <div style={styles.container}>
      <h2 style={styles.title}>📷 Reconnaissance faciale</h2>

      {/* Instructions */}
      <p style={styles.instructions}>
        Veuillez centrer votre visage, bien éclairé, avant de capturer.
      </p>

      <div style={styles.videoWrapper}>
        <video ref={videoRef} autoPlay playsInline style={styles.video} />
        <canvas ref={canvasRef} style={{ display: 'none' }} />
      </div>

      <div style={styles.controls}>
        {!streaming ? (
          <button onClick={startCamera} style={styles.button}>Démarrer caméra</button>
        ) : (
          <button onClick={stopCamera} style={styles.buttonDanger}>Arrêter caméra</button>
        )}
        <button onClick={captureImage} style={styles.button} disabled={!streaming}>
          Capturer
        </button>
        <button onClick={recognizeFace} style={styles.button} disabled={!capturedImage || loading}>
          {loading ? '⏳ Reconnaissance...' : 'Reconnaître'}
        </button>
        {capturedImage && (
          <button onClick={() => setCapturedImage(null)} style={styles.button}>
            Reprendre
          </button>
        )}
      </div>

      {capturedImage && (
        <div style={styles.previewBox}>
          <h4>Image capturée :</h4>
          <img src={capturedImage} alt="capture" style={styles.preview} />
        </div>
      )}

      {result && (
        <div style={styles.resultBox}>
          {result.status === 'success' && (
            <div style={styles.success}>
                ✅ Étudiant reconnu : <strong>{result.data.student_name}</strong><br />
                Email : {result.data.email || "Non disponible"}<br />
                Confiance : {(result.data.confidence * 100).toFixed(1)}%<br />
                Heure : {result.data.timestamp 
                  ? new Date(result.data.timestamp.replace(" ", "T")).toLocaleString('fr-FR') 
                  : "Non disponible"}<br />
                ID présence : {result.data.attendance_id || "N/A"}<br />
                Embedding ID : {result.data.matched_embedding_id || "N/A"}<br />
                {result.data.photo_path && (
                  <img 
                    src={result.data.photo_path} 
                    alt="Photo étudiant" 
                    style={{ width: "120px", marginTop: "8px", borderRadius: "6px" }} 
                  />
                )}
              </div>

          )}
          {result.status === 'nomatch' && (
            <div style={styles.warning}>⚠️ Visage inconnu</div>
          )}
          {result.status === 'noface' && (
            <div style={styles.error}>❌ Aucun visage détecté. Veuillez vous rapprocher de la caméra et réessayer.</div>
          )}
          {result.status === 'error' && (
            <div style={styles.error}>❌ Erreur : {result.error}</div>
          )}
        </div>
      )}
    </div>
  );
};

const styles = {
  container: { maxWidth: 600, margin: '20px auto', textAlign: 'center' },
  title: { marginBottom: 20, color: COLORS.textMain },
  instructions: { marginBottom: 10, color: COLORS.textMuted, fontSize: '0.9rem' },
  videoWrapper: { border: `1px solid ${COLORS.border}`, borderRadius: 8, overflow: 'hidden' },
  video: { width: '100%', height: 'auto' },
  controls: { display: 'flex', gap: 10, justifyContent: 'center', marginTop: 15, flexWrap: 'wrap' },
  button: { padding: '10px 20px', background: COLORS.primary, color: 'white', border: 'none', borderRadius: 6, cursor: 'pointer' },
  buttonDanger: { padding: '10px 20px', background: COLORS.danger, color: 'white', border: 'none', borderRadius: 6, cursor: 'pointer' },
  previewBox: { marginTop: 20 },
  preview: { maxWidth: '100%', borderRadius: 8 },
  resultBox: { marginTop: 20, padding: 15, borderRadius: 8 },
  success: { background: '#DCFCE7', color: '#166534', padding: 10, borderRadius: 6 },
  warning: { background: '#FEF3C7', color: '#92400E', padding: 10, borderRadius: 6 },
  error: { background: '#FEE2E2', color: '#991B1B', padding: 10, borderRadius: 6 }
};

export default CameraRecognition;
